// 简化自 RFC 6298 / linux tcp_input.c, 只为讲清三条线
class TcpSender {
    long srtt = -1;          // 平滑 RTT
    long rttvar = 0;         // RTT 偏差
    long rto = 1000;         // 初始 RTO 1s
    int dupAckCount = 0;     // 当前缺口的重复 ACK 数
    long highestAck = 0;     // 已确认最高字节
    boolean inFastRecovery = false;
    int cwnd = 10;           // 拥塞窗口(MSS)

    // 收到一个未重传段的 ACK 时调用,Karn 规则:重传段不更新 RTT
    void onRttSample(long rttMs, boolean wasRetransmitted) {
        if (wasRetransmitted) return;            // Karn: 跳过
        if (srtt < 0) {                          // 第一次测量
            srtt = rttMs;
            rttvar = rttMs / 2;
        } else {
            rttvar = (3 * rttvar + Math.abs(srtt - rttMs)) / 4;  // beta=1/4
            srtt   = (7 * srtt   + rttMs) / 8;                   // alpha=1/8
        }
        rto = Math.max(1000, srtt + 4 * rttvar); // 下限 1s
    }

    // 每收到一个 ACK 都判断:推进窗口 / 累计 dup-ACK / 触发快速重传
    void onAck(long ackNum, SackBlocks sack) {
        if (ackNum > highestAck) {
            highestAck = ackNum;
            dupAckCount = 0;                     // 新数据被确认,清零
            if (inFastRecovery) exitFastRecovery();
            return;
        }
        if (ackNum == highestAck) {              // 重复 ACK
            dupAckCount++;
            if (dupAckCount == 3 && !inFastRecovery) {
                retransmit(ackNum, sack);        // 快速重传:只补 SACK 之外的缺口
                cwnd /= 2;                       // 快速恢复:cwnd 减半
                inFastRecovery = true;
            }
        }
    }

    // RTO 触发时:更激进
    void onRtoTimeout(Segment seg) {
        retransmit(seg.seq, null);               // 不依赖 SACK,直接重发缺口
        cwnd = 1;                                // 退回慢启动
        rto = Math.min(rto * 2, 60_000);         // 指数退避,上限 60s
        seg.markRetransmitted();                 // 给 Karn 用
    }
}
